// Cross-language tests: the Solidity verifier must give exactly the same
// answers as the Python reference (fixtures generated by scripts/gen_fixtures.py).
const { expect } = require("chai");
const { ethers } = require("hardhat");
const fs = require("fs");

const load = (name) => JSON.parse(fs.readFileSync(`fixtures/${name}`, "utf8"));

describe("LayerVerifier (Solidity == Python)", function () {
  let h;
  before(async () => {
    h = await (await ethers.getContractFactory("VerifierHarness")).deploy();
  });

  it("Merkle proofs: every Python proof verifies on-chain", async () => {
    for (const c of load("merkle.json")) {
      expect(await h.verifyProof(c.leaf, c.index, c.proof, c.root)).to.equal(true);
    }
  });

  it("Merkle proofs: a wrong index fails", async () => {
    const c = load("merkle.json").find((x) => x.proof.length > 0);
    expect(await h.verifyProof(c.leaf, c.index ^ 1, c.proof, c.root)).to.equal(false);
  });

  it("Freivalds: Solidity result == Python result on all random cases", async () => {
    const cases = load("freivalds.json");
    let accepted = 0, rejected = 0;
    for (const c of cases) {
      const got = await h.freivalds(c.W, c.b, c.nIn, c.nOut, c.xs, c.accs, c.seed, c.layer);
      expect(got).to.equal(c.expected);
      got ? accepted++ : rejected++;
    }
    expect(accepted).to.be.greaterThan(0);
    expect(rejected).to.be.greaterThan(0);
  });

  it("Leaf hashes match the Python tree roots (honest job)", async () => {
    const job = load("job_none.json");
    const l1 = job.layers[0];
    // item 0, layer 1: x proven against inputRoot, y against activationRoot
    const xLeaf = await h.inputLeaf(0, l1.xs[0]);
    expect(await h.verifyProof(xLeaf, 0, l1.xProofs[0], job.inputRoot)).to.equal(true);
    const yLeaf = await h.activationLeaf(0, 1, l1.ys[0]);
    expect(await h.verifyProof(yLeaf, 0, l1.yProofs[0], job.activationRoot)).to.equal(true);
  });

  it("Requantization: honest traces pass, a changed output fails", async () => {
    const job = load("job_none.json");
    const L = job.layers.length;
    for (let l = 0; l < L; l++) {
      const layer = job.layers[l];
      const nOut = job.dims[l + 1];
      const lo = l === L - 1 ? -128 : 0;
      for (let t = 0; t < job.numItems; t++) {
        expect(await h.requantOk(layer.accs[t], layer.ys[t], nOut, layer.M, layer.s, lo, 127)).to.equal(true);
      }
    }
    const l1 = job.layers[0];
    const y = ethers.getBytes(l1.ys[0]);
    y[0] = (y[0] + 1) % 128;
    expect(await h.requantOk(l1.accs[0], y, job.dims[1], l1.M, l1.s, 0, 127)).to.equal(false);
  });
});
